  padding-top: 0;
  gap: 8px;
}
.v-alert[data-slot][data-presentation] .v-alert__kicker {
  color: var(--v-text-2);
  font-size: 10px;
  letter-spacing: 0.04em;
}
.v-alert[data-slot][data-presentation] .v-alert__actions {
  margin-top: 8px;
  gap: 8px;
}
.v-alert[data-slot] .v-alert__actions .v-btn {
  min-height: 44px;
  height: auto;
  padding: 8px 16px;
}
.v-alert[data-slot][data-presentation] > .v-alert__blob {
  --mfill: var(--alert-accent);
  background: var(--alert-accent);
  color: var(--v-on-accent);
}
.v-alert[data-slot][data-presentation] > .v-alert__blob > .v-icon {
  color: var(--v-on-accent);
}
.v-alert[data-slot][data-presentation] > .v-alert__blob:has(> svg.v-morph) {
  background: transparent;
}
.v-alert[data-slot][data-presentation] > .v-alert__close {
  background: transparent;
  color: var(--v-text-2);
}
.v-alert[data-slot][data-presentation]:has(.v-alert__close) .v-alert__body {
  padding-inline-end: 30px;
}
.v-alert[data-slot][data-presentation="note"] {
  border-inline-start: 4px solid var(--alert-accent);
  border-radius: 4px min(var(--v-control-radius, 20px), 28px)
    min(var(--v-control-radius, 20px), 28px) 4px;
}
.v-alert[data-slot][data-presentation="banner"] {
  border-radius: 12px;
  background: color-mix(in srgb, var(--alert-accent) 10%, var(--v-canvas));
  grid-template-columns: 40px minmax(0, 1fr);
  align-items: center;
  padding: 16px 20px;
}
.v-alert[data-slot][data-presentation="banner"] .v-alert__body {
  grid-template-columns: minmax(0, 1fr) auto;
  column-gap: 16px;
  align-items: center;
}
.v-alert[data-slot][data-presentation="banner"] .v-alert__title {
  font-size: 16px;
}
.v-alert[data-slot][data-presentation="banner"] .v-alert__kicker {
  display: none;
}
.v-alert[data-slot][data-presentation="banner"] .v-alert__title,
.v-alert[data-slot][data-presentation="banner"] .v-alert__text {
  grid-column: 1;
}
.v-alert[data-slot][data-presentation="banner"] .v-alert__actions {
  grid-column: 2;
  grid-row: 1/3;
  margin: 0;
}
.v-alert[data-slot][data-presentation="dispatch"] {
  grid-template-columns: minmax(0, 1fr);
  padding: 24px 28px;
  border-radius: 4px 24px 24px 24px;
  background: linear-gradient(
    135deg,
    color-mix(in srgb, var(--alert-accent) 10%, var(--v-canvas)),
    var(--v-canvas) 70%
  );
}
.v-alert[data-slot][data-presentation="dispatch"] > .v-alert__blob {
  width: 48px;
  height: 48px;
}
.v-alert[data-slot][data-presentation="dispatch"] .v-alert__title {
  font-size: 24px;
  max-width: 26ch;
}
.v-alert[data-slot][data-presentation="dispatch"] .v-alert__actions {
  border-top: 1px dashed var(--v-border);
  padding-top: 14px;
  margin-top: 12px;
}
.v-alert[data-slot][data-presentation="dispatch"] .v-alert__body {
  padding-inline-end: 0;
}
.v-alert[data-slot][data-presentation="dispatch"]::before {
  content: "";
  position: absolute;
  inset: auto 0 0 auto;
  width: 24px;
  height: 24px;
  pointer-events: none;
  background: linear-gradient(
    135deg,
    transparent 48%,
    var(--v-border) 50%,
    color-mix(in srgb, var(--alert-accent) 25%, var(--v-canvas)) 54%
  );
}
@container (max-width:460px) {
  .v-alert[data-slot][data-presentation="banner"] > .v-alert__blob {
    align-self: start;
  }
  .v-alert[data-slot][data-presentation="banner"] .v-alert__body {
    grid-template-columns: minmax(0, 1fr);
  }
  .v-alert[data-slot][data-presentation="banner"] .v-alert__actions {
    grid-column: 1;
    grid-row: auto;
    margin-top: 8px;
  }
}
.v-message-example {
  width: 100%;
  min-width: 0;
  display: grid;
  gap: 16px;
}
.v-message-example__hint {
  margin: 0;
  color: var(--v-text-2);
  font-size: 11px;
  line-height: 1.6;
}
.v-message-example__restored {
  display: flex;
  align-items: center;
  gap: 16px;
  justify-content: space-between;
  flex-wrap: wrap;
  min-height: 100px;
  padding: 20px;
  border: 1px dashed var(--v-border);
  border-radius: 16px;
}
.v-message-example__restored p {
  margin: 0;
  font-size: 13px;
  color: var(--v-text-2);
}
.v-message-example__notes {
  border-inline-start: 2px solid var(--v-blue);
  padding: 4px 0 4px 18px;
}
.v-message-example__notes h4 {
  font-size: 15px;
  font-weight: var(--fw-title);
  margin: 0 0 8px;
}
.v-message-example__notes ul {
  padding: 0;
  margin: 0;
  list-style: none;
  display: grid;
  gap: 8px;
}
.v-message-example__notes li {
  display: flex;
  gap: 12px;
  align-items: baseline;
  font-size: 13px;
  color: var(--v-text-2);
}
.v-message-example__notes li span {
  font-family: var(--font-mono);
  font-size: 10px;
}

}
